// This file is not generated by Stainless and is preserved across codegen runs.
// It holds unit tests for the no-op handling in the hand-written *UpdateAndPoll
// convenience methods (GCLOUD2-27266).
//
// The Cloud API skips task creation when an update does not change the resource
// (e.g. a tags-only update), returning HTTP 200 with an empty task list. The
// UpdateAndPoll helpers must treat that as a completed no-op — return the
// current resource via Get instead of erroring on the missing task.
//
// The tests are self-contained: each drives a local httptest.Server that
// emulates the Cloud async task flow, so they run under a plain `go test` (or
// `scripts/test`) without needing the Prism/Steady mock server.

package cloud_test

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/G-Core/gcore-go"
	"github.com/G-Core/gcore-go/cloud"
	"github.com/G-Core/gcore-go/option"
)

const updateAndPollResourceID = "00000000-0000-4000-8000-000000000001"

// newUpdateFlowServer emulates the Cloud async flow for an update:
//   - the PATCH action returns a TaskIDList with the given task IDs (pass an
//     empty slice to emulate a no-op update where the API creates no task)
//   - GET .../tasks/{id} returns a FINISHED task
//   - any other GET (the final resource fetch) returns a permissive object that
//     unmarshals into every resource type
func newUpdateFlowServer(actionTasks []string) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/tasks/"):
			// Shape captured from a real FINISHED update_router task on the Cloud API.
			_ = json.NewEncoder(w).Encode(map[string]any{
				"id":                  "6465bbb6-6009-4f2c-89e5-4ccffabdf98f",
				"state":               cloud.TaskStateFinished,
				"task_type":           "update_router",
				"client_id":           3621,
				"user_id":             4585,
				"user_client_id":      3621,
				"project_id":          379987,
				"region_id":           76,
				"detailed_state":      nil,
				"request_id":          "a5700e8820e3f8d6e30d8d814472a0ea",
				"error":               nil,
				"created_on":          "2026-07-01T13:33:36",
				"updated_on":          "2026-07-01T13:33:37",
				"finished_on":         "2026-07-01T13:33:37",
				"acknowledged_at":     nil,
				"acknowledged_by":     nil,
				"job_id":              nil,
				"schedule_id":         nil,
				"lifecycle_policy_id": nil,
			})
		case r.Method == http.MethodGet:
			_, _ = w.Write([]byte(`{}`))
		default: // the update action
			_ = json.NewEncoder(w).Encode(map[string]any{"tasks": actionTasks})
		}
	}))
}

func newUpdateFlowClient(server *httptest.Server) gcore.Client {
	return gcore.NewClient(
		option.WithBaseURL(server.URL),
		option.WithAPIKey("test"),
		// Project/region defaults satisfy the required path params that the
		// generated methods validate before issuing a request.
		option.WithCloudProjectID(1),
		option.WithCloudRegionID(1),
	)
}

