// TestUpdateAndPollNoOp is the core regression for GCLOUD2-27266: an update that
// creates no task (empty task list) must succeed as a no-op rather than erroring
// with "expected at least one task to be created".
func TestUpdateAndPollNoOp(t *testing.T) {
	server := newUpdateFlowServer([]string{}) // no task created
	defer server.Close()
	client := newUpdateFlowClient(server)

	for _, tc := range updateAndPollMethods {
		t.Run(tc.name, func(t *testing.T) {
			if err := tc.invoke(context.Background(), client); err != nil {
				t.Fatalf("%s should treat an empty task list as a successful no-op, got error: %s", tc.name, err)
			}
		})
	}
}

// TestUpdateAndPollWithTask covers the normal path: the update creates a task,
// which is polled to completion before returning the refreshed resource.
func TestUpdateAndPollWithTask(t *testing.T) {
	server := newUpdateFlowServer([]string{"task-1"})
	defer server.Close()
	client := newUpdateFlowClient(server)

	for _, tc := range updateAndPollMethods {
		t.Run(tc.name, func(t *testing.T) {
			if err := tc.invoke(context.Background(), client); err != nil {
				t.Fatalf("%s returned an unexpected error: %s", tc.name, err)
			}
		})
	}
}

